{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/post-grid.json
    A section with a heading and the posts as cards: a grid, a list of horizontal cards, or a magazine (the first post wide, the rest in a grid). Axes: layout (grid, list, magazine), columns, media, meta (full, short, news), filter mode (none, topics), tone, density.
    Props (p): id, title, posts, labels, action, filter, layout, cols, media, meta, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_posts = ($p['posts'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_action = ($p['action'] ?? null)}
{var $v_filter = ($p['filter'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'grid')}
{var $v_cols = ($p['cols'] ?? '1-3')}
{var $v_media = ($p['media'] ?? 'image')}
{var $v_meta = ($p['meta'] ?? 'full')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_6}
  {if ui_t(ui_eq(ui_get($v_filter, ['mode']), 'topics'))}
    {capture $c_2}
      {foreach ui_l(ui_get($v_filter, ['topics'])) as $v_tab}
        {capture $c_1}
          {=ui_text(ui_get($v_tab, ['title']))}
        {/capture}
        {=ui_include('blocks/switcher-item.latte', ['p' => ['active' => ui_eq(ui_get($v_tab, ['value']), ui_get($v_filter, ['topic']))], 'children' => $c_1])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('blocks/switcher.latte', ['p' => ['label' => ui_get($v_filter, ['label'])], 'children' => $c_2])|noescape}
  {/if}
  {if ui_t(ui_eq($v_layout, 'magazine'))}
    {capture $c_4}
      {foreach ui_l(ui_where($v_posts, 'category', ui_get($v_filter, ['topic']))) as $v_p}
        {var $v_i = $iterator->counter0}
        {if ui_t(ui_eq($v_i, 0))}
          {=ui_include('blocks/post-card.latte', ['p' => ['post' => $v_p, 'labels' => $v_labels, 'layout' => 'horizontal', 'media' => $v_media, 'meta' => $v_meta, 'density' => $v_density]])|noescape}
        {/if}
      {/foreach}
      {capture $c_3}
        {foreach ui_l(ui_where($v_posts, 'category', ui_get($v_filter, ['topic']))) as $v_p}
          {var $v_i = $iterator->counter0}
          {if ui_t(ui_gt($v_i, 0))}
            {=ui_include('blocks/post-card.latte', ['p' => ['post' => $v_p, 'labels' => $v_labels, 'media' => $v_media, 'meta' => $v_meta, 'density' => $v_density]])|noescape}
          {/if}
        {/foreach}
      {/capture}
      {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s($v_cols), 'Class' => 'gap-6'], 'children' => $c_3])|noescape}
    {/capture}
    {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '6', 'Align' => 'stretch', 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_4])|noescape}
  {else}
    {capture $c_5}
      {foreach ui_l(ui_where($v_posts, 'category', ui_get($v_filter, ['topic']))) as $v_p}
        {=ui_include('blocks/post-card.latte', ['p' => ['post' => $v_p, 'labels' => $v_labels, 'layout' => (ui_t(ui_eq($v_layout, 'list')) ? 'horizontal' : 'vertical'), 'media' => $v_media, 'meta' => $v_meta, 'density' => $v_density]])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s((ui_t(ui_eq($v_layout, 'list')) ? '1' : ui_fit_cols($v_cols, ui_len(ui_where($v_posts, 'category', ui_get($v_filter, ['topic'])))))), 'Class' => 'w-full gap-6', 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_5])|noescape}
  {/if}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'action' => $v_action, 'tone' => $v_tone, 'density' => (ui_t(ui_eq($v_density, 'compact')) ? 'compact' : 'default'), 'measure' => (ui_t(ui_eq($v_meta, 'news')) ? 'fill' : 'default'), 'className' => ui_cnv([(ui_t(ui_eq($v_meta, 'news')) ? 'py-0' : '')]), 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_6])|noescape}
